const fs = require("fs");
const path = require("path");
const schema = require("./schema");

const lines = [
  "-- Generated by `npm run db:ddl` from db/schema.js. Do not edit by hand.",
  "-- Replace `your_project.finance_apps` with your project and dataset.",
  "",
  "CREATE SCHEMA IF NOT EXISTS `your_project.finance_apps`;",
  "",
];

for (const [table, cols] of Object.entries(schema)) {
  const width = Math.max(...cols.map((c) => c.name.length));
  lines.push(`CREATE OR REPLACE TABLE \`your_project.finance_apps.${table}\` (`);
  lines.push(cols.map((c) => `  ${c.name.padEnd(width)} ${c.type}`).join(",\n"));
  lines.push(");", "");
}

fs.writeFileSync(path.join(__dirname, "schema.sql"), lines.join("\n"));
console.log("Wrote db/schema.sql");
